const fn = new Function(code + "\nreturn { gatherReport };");
const { gatherReport } = fn();
const out = await gatherReport([
  { name: "user", run: () => Promise.resolve({ id: 1 }) },
  { name: "orders", run: () => Promise.reject(new Error("503")) },
  { name: "notifs", run: () => Promise.resolve(["a"]) },
]);
if (out.ok.user.id !== 1 || out.ok.notifs.join() !== "a") throw new Error("Fulfilled values should be keyed by name.");
if (out.broken.join() !== "orders") throw new Error("Rejected fetcher names go into broken.");

